  "factsKnown": [
    {
      "id": "ye-initial",
      "summary": "知道低潮碎石滩危险、渡口至灯塔航程四十分钟；不知道暗格和七分钟",
      "sourceChapterRef": "chapter:chapter-001.md"
    },
    {
      "id": "ye-ch3",
      "summary": "沿正规航道行船，听见船底异响并钩出缠着黑浮木的断缆；确认回舵后续航，因停船检查三分钟于21:03抵诊所，执照登记并要求交接单写明正规航道到达",
      "sourceChapterRef": "chapter:chapter-003.md"
    }
  ],
  "emotionalMemory": [
    {
      "id": "ye-ch3",
      "summary": "担心雾航与漂木损及船和执照，查明船况后才恢复航行；对众人把秘密带上船感到不耐烦"
    }
  ],
  "relationshipDeltas": [
    {
      "id": "ye-ch3",
      "summary": "履行欠何芷的人情并把药送达；与陆行舟在船上处置异响时协作多于争运价"
    }
  ],
  "unresolvedIntentions": [
    {
      "id": "ye-goal",
      "summary": "保住执照与船员"
    },
    {
      "id": "ye-next-ch3",
      "summary": "守住执照与船员，交代完整航程和检查记录，不替任何人担保账页秘密"
    }
  ],
  "privateMisbeliefs": []
}"
}

